/// Result of a block multi-source solve: one column per source RHS.
pub(super) struct BlockSourceSolve {
    /// Solution block, n × k (column j = source j).
    pub(super) x: DenseMatrix<Complex64>,
    /// Total block Arnoldi steps performed.
    pub(super) iterations: usize,
    /// Recomputed true relative residual per source, `‖b_j − A·x_j‖ / ‖b_j‖`.
    /// The caller gates each source on this and routes failures to the
    /// per-source fallback ladder.
    pub(super) true_residuals: Vec<f64>,
}

/// Solve all source right-hand sides of one frequency as a single block
/// system, dispatching on the same flexible-outer rule as the per-source
/// path: block FGMRES for flexible (AMG) preconditioners, block GMRES
/// otherwise. Warm-start `x0` is the stacked previous-frequency solution
/// block; per-source subspace recycling is intentionally not used here
/// (block GCRO-DR is future work).
///
/// The block solvers recompute per-RHS true residuals at exit, so no
/// additional verification pass is needed here; per-source defect
/// correction stays on the fallback path for any RHS that fails the gate.
pub(super) fn solve_frequency_block(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs_block: &DenseMatrix<Complex64>,
    x0: Option<&DenseMatrix<Complex64>>,
    config: &GmresConfig<f64>,
) -> BlockSourceSolve {
    if preconditioner.uses_flexible_outer() {
        let block_config = BlockFgmresConfig {
            max_iterations: config.max_iterations,
            restart: config.restart,
            tolerance: config.tolerance,
            true_residual_check: true,
            exact_residual_check_interval: config.exact_residual_check_interval,
        };
        let result = block_fgmres_preconditioned_with_guess(
            operator,
            rhs_block,
            preconditioner,
            x0,
            &block_config,
        );
        BlockSourceSolve {
            x: result.x,
            iterations: result.iterations,
            true_residuals: result.true_residuals,
        }
    } else {
        let block_config = BlockGmresConfig {
            max_iterations: config.max_iterations,
            restart: config.restart,
            tolerance: config.tolerance,
            true_residual_check: true,
            exact_residual_check_interval: config.exact_residual_check_interval,
        };
        let result = block_gmres_preconditioned_with_guess(
            operator,
            rhs_block,
            preconditioner,
            x0,
            &block_config,
        );
        BlockSourceSolve {
            x: result.x,
            iterations: result.iterations,
            true_residuals: result.true_residuals,
        }
    }
}

fn validate_source_blocks(
    source_count: usize,
    source_blocks: &[(usize, usize)],
) -> Result<(), String> {
    if source_blocks.is_empty() {
        return Err("source-block solve requires at least one block".into());
    }
    let mut expected_start = 0;
    for &(source_start, block_count) in source_blocks {
        if block_count == 0 || source_start != expected_start {
            return Err("source blocks must be non-empty and contiguous".into());
        }
        expected_start = expected_start
            .checked_add(block_count)
            .ok_or_else(|| "source-block range overflow".to_string())?;
        if expected_start > source_count {
            return Err("source block exceeds RHS column count".into());
        }
    }
    if expected_start != source_count {
        return Err("source blocks must cover every RHS column".into());
    }
    Ok(())
}

fn source_block_rhs(
    rhs: &DenseMatrix<Complex64>,
    source_start: usize,
    source_count: usize,
) -> DenseMatrix<Complex64> {
    let mut block = DenseMatrix::from_elem(rhs.nrows(), source_count, Complex64::new(0.0, 0.0));
    for local_index in 0..source_count {
        block.set_column(local_index, &rhs.column_to_vec(source_start + local_index));
    }
    block
}

fn source_block_guess(
    guess: Option<&DenseMatrix<Complex64>>,
    source_start: usize,
    source_count: usize,
) -> Option<DenseMatrix<Complex64>> {
    guess.map(|guess| {
        let mut block =
            DenseMatrix::from_elem(guess.nrows(), source_count, Complex64::new(0.0, 0.0));
        for local_index in 0..source_count {
            block.set_column(
                local_index,
                &guess.column_to_vec(source_start + local_index),
            );
        }
        block
    })
}

fn combine_source_blocks(
    source_count: usize,
    source_blocks: &[(usize, usize)],
    solved_blocks: Vec<BlockSourceSolve>,
) -> BlockSourceSolve {
    let rows = solved_blocks[0].x.nrows();
    let mut x = DenseMatrix::from_elem(rows, source_count, Complex64::new(0.0, 0.0));
    let mut true_residuals = vec![0.0; source_count];
    let mut iterations = 0;
    for ((source_start, block_count), solved) in source_blocks.iter().zip(solved_blocks) {
        iterations += solved.iterations;
        for local_index in 0..*block_count {
            x.set_column(
                source_start + local_index,
                &solved.x.column_to_vec(local_index),
            );
            true_residuals[source_start + local_index] = solved.true_residuals[local_index];
        }
    }
    BlockSourceSolve {
        x,
        iterations,
        true_residuals,
    }
}

/// Solve a frequency's RHS columns according to the admitted source-block
/// topology. Independent blocks run concurrently and are reassembled in
/// source order so the caller retains the existing result contract.
pub(super) fn solve_frequency_block_partitioned(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs: &DenseMatrix<Complex64>,
    x0: Option<&DenseMatrix<Complex64>>,
    config: &GmresConfig<f64>,
    source_blocks: &[(usize, usize)],
) -> Result<BlockSourceSolve, String> {
    validate_source_blocks(rhs.ncols(), source_blocks)?;
    let solved_blocks = source_blocks
        .par_iter()
        .map(|&(source_start, source_count)| {
            let rhs_block = source_block_rhs(rhs, source_start, source_count);
            let x0_block = source_block_guess(x0, source_start, source_count);
            solve_frequency_block(
                operator,
                preconditioner,
                &rhs_block,
                x0_block.as_ref(),
                config,
            )
        })
        .collect();
    Ok(combine_source_blocks(
        rhs.ncols(),
        source_blocks,
        solved_blocks,
    ))
}

/// Cancellation-aware counterpart of [`solve_frequency_block_partitioned`].
///
/// Each admitted source block is independent, so the blocks may execute in
/// parallel. The result is still assembled in planner/source order, and a
/// cancellation or solver error prevents a partial block result from being
/// published to the caller.
pub(super) fn solve_frequency_block_partitioned_with_abort<F>(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs: &DenseMatrix<Complex64>,
    x0: Option<&DenseMatrix<Complex64>>,
    config: &GmresConfig<f64>,
    source_blocks: &[(usize, usize)],
    should_abort: F,
) -> Result<BlockSourceSolve, String>
where
    F: Fn() -> bool + Sync,
{
    validate_source_blocks(rhs.ncols(), source_blocks)?;
    if should_abort() {
        return Err("source-block cancellation requested".into());
    }

    let solved_blocks: Result<Vec<_>, _> = source_blocks
        .par_iter()
        .map(|&(source_start, source_count)| {
            let rhs_block = source_block_rhs(rhs, source_start, source_count);
            let x0_block = source_block_guess(x0, source_start, source_count);
            solve_frequency_block_with_abort(
                operator,
                preconditioner,
                &rhs_block,
                x0_block.as_ref(),
                config,
                &should_abort,
            )
        })
        .collect();

    Ok(combine_source_blocks(
        rhs.ncols(),
        source_blocks,
        solved_blocks?,
    ))
}

/// Solve a source block with a caller-owned cooperative abort hook.
///
/// The ordinary block path deliberately remains infallible for the legacy
/// production loop. Cancellation-aware FEM runs use the checked solver
/// boundary instead, so an abort cannot be mistaken for a converged partial
/// block. Flexible preconditioners use the checked scalar FGMRES boundary for
/// each RHS because the block-FGMRES compatibility entry point does not yet
/// expose the same abort contract.
pub(super) fn solve_frequency_block_with_abort<F>(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs_block: &DenseMatrix<Complex64>,
    x0: Option<&DenseMatrix<Complex64>>,
    config: &GmresConfig<f64>,
    should_abort: F,
) -> Result<BlockSourceSolve, String>
where
    F: Fn() -> bool,
{
    if preconditioner.uses_flexible_outer() {
        let fgmres_config = fgmres_config_from_gmres(config);
        let mut x = DenseMatrix::from_elem(
            rhs_block.nrows(),
            rhs_block.ncols(),
            Complex64::new(0.0, 0.0),
        );
        let mut true_residuals = Vec::with_capacity(rhs_block.ncols());
        let mut iterations = 0;
        for source_index in 0..rhs_block.ncols() {
            if should_abort() {
                return Err("FGMRES cancellation requested".into());
            }
            let rhs = rhs_block.column_to_vec(source_index);
            let initial_guess = x0.map(|guess| guess.column_to_vec(source_index));
            let result = try_fgmres_preconditioned_with_abort(
                operator,
                preconditioner,
                &rhs,
                initial_guess.as_deref(),
                &fgmres_config,
                &should_abort,
            )
            .map_err(|error| error.to_string())?;
            iterations += result.iterations;
            true_residuals.push(result.residual);
            x.set_column(source_index, &result.x);
        }
        return Ok(BlockSourceSolve {
            x,
            iterations,
            true_residuals,
        });
    }

    let block_config = BlockGmresConfig {
        max_iterations: config.max_iterations,
        restart: config.restart,
        tolerance: config.tolerance,
        true_residual_check: true,
        exact_residual_check_interval: config.exact_residual_check_interval,
    };
    let result = try_block_gmres_preconditioned_with_abort(
        operator,
        rhs_block,
        preconditioner,
        x0,
        &block_config,
        should_abort,
    )
    .map_err(|error| error.to_string())?;
    Ok(BlockSourceSolve {
        x: result.x,
        iterations: result.iterations,
        true_residuals: result.true_residuals,
    })
}

pub(super) fn solve_frequency_system(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs: &[Complex64],
    x0: Option<&[Complex64]>,
    recycled_subspace: Option<&mut FemRecycleSubspace>,
    config: &GmresConfig<f64>,
) -> GmresSolution<Complex64> {
    let mut result = if preconditioner.uses_flexible_outer() {
        let fgmres_config = fgmres_config_from_gmres(config);
        fgmres_to_gmres_solution(fgmres_preconditioned(
            operator,
            preconditioner,
            rhs,
            x0,
            &fgmres_config,
        ))
    } else {
        match recycled_subspace {
            Some(FemRecycleSubspace(sub)) => {
                let cfg = GcroDrConfig::from_gmres(config);
                gcro_dr_preconditioned(operator, preconditioner, rhs, x0, sub, &cfg)
            }
            None => gmres_preconditioned_with_guess(operator, preconditioner, rhs, x0, config),
        }
    };

    // Krylov recurrences can report a small projected residual while the true
    // residual has drifted, especially around a nearly singular Helmholtz
    // pole or after recycling.  Never accept a room response without one
    // explicit A*x verification against the assembled physical operator.
    result.residual = true_relative_residual(operator, &result.x, rhs);
    // If the projected recurrence stopped a little early, solve the actual
    // defect A*delta = b-A*x.  Two cheap refinement steps are much more
    // reliable than restarting the original solve from the prior frequency,
    // and retain the requested tolerance even at high-Q poles.
    for _ in 0..MAX_DEFECT_CORRECTIONS {
        if result.residual.is_finite() && result.residual <= config.tolerance {
            break;
        }
        let defect = residual_vector(operator, &result.x, rhs);
        let correction = if preconditioner.uses_flexible_outer() {
            fgmres_to_gmres_solution(fgmres_preconditioned(
                operator,
                preconditioner,
                &defect,
                None,
                &fgmres_config_from_gmres(config),
            ))
        } else {
            gmres_preconditioned_with_guess(operator, preconditioner, &defect, None, config)
        };
        result.iterations += correction.iterations;
        for (x, delta) in result.x.iter_mut().zip(correction.x) {
            *x += delta;
        }
        result.residual = true_relative_residual(operator, &result.x, rhs);
    }
    result.converged = result.residual.is_finite() && result.residual <= config.tolerance;
    result
}

/// Solve one RHS through an abort-aware checked FGMRES boundary.
///
/// This intentionally does not use GCRO-DR or the defect-retry ladder: those
/// compatibility APIs do not accept an abort callback. The caller can retry
/// a non-cancelled numerical failure through the normal path, while a checked
/// cancellation is returned before any partial solution is published.
pub(super) fn solve_frequency_system_with_abort<F>(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs: &[Complex64],
    x0: Option<&[Complex64]>,
    config: &GmresConfig<f64>,
    should_abort: F,
) -> Result<GmresSolution<Complex64>, String>
where
    F: Fn() -> bool,
{
    let result = try_fgmres_preconditioned_with_abort(
        operator,
        preconditioner,
        rhs,
        x0,
        &fgmres_config_from_gmres(config),
        should_abort,
    )
    .map_err(|error| error.to_string())?;
    Ok(fgmres_to_gmres_solution(result))
}

pub(super) fn solve_frequency_system_bicgstab(
    operator: &CsrMatrix<Complex64>,
    preconditioner: &FemPreconditioner,
    rhs: &[Complex64],
    x0: Option<&[Complex64]>,
    tolerance: f64,
) -> GmresSolution<Complex64> {
    let config = BiCgstabConfig {
        max_iterations: BICGSTAB_FALLBACK_MAX_ITERATIONS,
        tolerance,
        print_interval: 0,
    };
    let result =
        bicgstab_pipelined_preconditioned_with_guess(operator, preconditioner, rhs, x0, &config);
    let residual = true_relative_residual(operator, &result.x, rhs);
    let ax = operator.matvec(&result.x);
    let mut residual_norm_sq = 0.0;
    let mut ax_norm_sq = 0.0;
    let mut rhs_norm_sq = 0.0;
    for (&rhs_value, &applied) in rhs.iter().zip(&ax) {
        let error = rhs_value - applied;
        residual_norm_sq += error.norm_sqr();
        ax_norm_sq += applied.norm_sqr();
        rhs_norm_sq += rhs_value.norm_sqr();
    }
    let backward_error =
        residual_norm_sq.sqrt() / (ax_norm_sq.sqrt() + rhs_norm_sq.sqrt()).max(1.0);
    GmresSolution {
        x: result.x,
        iterations: result.iterations,
        restarts: 0,
        residual,
        estimated_residual: result.residual,
        backward_error,
        attainable_accuracy: if residual <= tolerance {
            AccuracyStatus::Attained
        } else {
            AccuracyStatus::NotAttained
        },
        converged: residual.is_finite() && residual <= tolerance,
        status: result.status,
        op_counts: result.op_counts,
    }
}

#[cfg(test)]
mod partitioned_tests {
    use super::*;
    use num_complex::Complex64;
    use sonium_solvers::dense::DenseMatrix;
    use sonium_solvers::preconditioners::IlutPreconditioner;

    fn identity_problem() -> (
        CsrMatrix<Complex64>,
        FemPreconditioner,
        DenseMatrix<Complex64>,
    ) {
        let operator = CsrMatrix::identity(2);
        let preconditioner = FemPreconditioner::Ilut(IlutPreconditioner::from_csr(&operator));
        let mut rhs = DenseMatrix::from_elem(2, 3, Complex64::new(0.0, 0.0));
        rhs.set_column(0, &[Complex64::new(1.0, 0.0), Complex64::new(2.0, 0.0)]);
        rhs.set_column(1, &[Complex64::new(3.0, 0.0), Complex64::new(5.0, 0.0)]);
        rhs.set_column(2, &[Complex64::new(7.0, 0.0), Complex64::new(11.0, 0.0)]);
        (operator, preconditioner, rhs)
    }

    #[test]
    fn partitioned_block_solve_reassembles_source_order() {
        let (operator, preconditioner, rhs) = identity_problem();
        let solved = solve_frequency_block_partitioned(
            &operator,
            &preconditioner,
            &rhs,
            None,
            &GmresConfig::default(),
            &[(0, 1), (1, 2)],
        )
        .expect("partitioned identity solve should converge");

        for source_index in 0..rhs.ncols() {
            let solved_column = solved.x.column_to_vec(source_index);
            let rhs_column = rhs.column_to_vec(source_index);
            assert!(
                solved_column
                    .iter()
                    .zip(rhs_column)
                    .all(|(actual, expected)| (*actual - expected).norm() <= 1.0e-12)
            );
            assert!(solved.true_residuals[source_index] <= 1.0e-12);
        }
        assert!(solved.iterations > 0);
    }

    #[test]
    fn partitioned_block_solve_rejects_gaps_and_pre_cancelled_runs() {
        let (operator, preconditioner, rhs) = identity_problem();
        let config = GmresConfig::default();
        assert!(
            solve_frequency_block_partitioned(
                &operator,
                &preconditioner,
                &rhs,
                None,
                &config,
                &[(0, 1), (2, 1)],
            )
            .is_err()
        );

        let error = match solve_frequency_block_partitioned_with_abort(
            &operator,
            &preconditioner,
            &rhs,
            None,
            &config,
            &[(0, 1), (1, 2)],
            || true,
        ) {
            Ok(_) => panic!("pre-cancelled partition must not publish a result"),
            Err(error) => error,
        };
        assert!(error.contains("cancellation"));
    }
}

#[cfg(test)]
mod cancellation_tests {
    use super::*;
    use num_complex::Complex64;
    use sonium_solvers::dense::DenseMatrix;
    use sonium_solvers::preconditioners::IlutPreconditioner;
    use std::sync::atomic::{AtomicUsize, Ordering};

    fn identity_problem() -> (
        CsrMatrix<Complex64>,
        FemPreconditioner,
        DenseMatrix<Complex64>,
    ) {
        let operator = CsrMatrix::identity(2);
        let preconditioner = FemPreconditioner::Ilut(IlutPreconditioner::from_csr(&operator));
        let mut rhs = DenseMatrix::from_elem(2, 1, Complex64::new(0.0, 0.0));
        rhs.set_column(0, &[Complex64::new(1.0, 0.0), Complex64::new(2.0, 0.0)]);
        (operator, preconditioner, rhs)
    }

    #[test]
    fn block_cancellation_is_a_typed_error_before_partial_publish() {
        let (operator, preconditioner, rhs) = identity_problem();
        let polls = AtomicUsize::new(0);
        let result = solve_frequency_block_with_abort(
            &operator,
            &preconditioner,
            &rhs,
            None,
            &GmresConfig::default(),
            || polls.fetch_add(1, Ordering::SeqCst) >= 1,
        );
        let error = match result {
            Ok(_) => panic!("cancelled block solve must not publish a result"),
            Err(error) => error,
        };
        assert!(error.contains("abort"));
    }

    #[test]
    fn scalar_cancellation_is_a_typed_error_before_partial_publish() {
        let (operator, preconditioner, rhs) = identity_problem();
        let rhs = rhs.column_to_vec(0);
        let polls = AtomicUsize::new(0);
        let error = solve_frequency_system_with_abort(
            &operator,
            &preconditioner,
            &rhs,
            None,
            &GmresConfig::default(),
            || polls.fetch_add(1, Ordering::SeqCst) >= 1,
        )
        .expect_err("cancelled scalar solve must not publish a result");
        assert!(error.contains("termination") || error.contains("abort"));
    }
}
